(() => {
'use strict';
const $=id=>document.getElementById(id),states=['Menu','Level','Prep','Going Hot','Downed','Recovery','Credits','Custom'],roles=['Riff','Stem','Finished mix','Alternate song'];
let inputs=[],confirmations={};
const snapshot=()=>window.PulseProjectStatus?.()||{};
const clean=s=>String(s).slice(0,100);
function readiness(){const p=snapshot(),approved=p.clips?.filter(c=>c.approved)||[],events=new Set(approved.map(c=>c.event));const checks=[['Finished mix loaded',!!p.source],['BPM and meter confirmed by listening',!!confirmations.meter],['Reviewed loops included',approved.length>0],['Each needed game state has an approved clip',!!confirmations.coverage],['Loop joins heard and approved',!!confirmations.joins],['Transitions saved for the intended state changes',p.rules>0],['Mix, levels and clipping approved by a creator',!!confirmations.mix],['Imported and tested in the target game engine',!!confirmations.engine]];return {checks,approved:approved.length,events:[...events]}}
function refresh(){const list=$('projectInputList');list.replaceChildren();if(!inputs.length)list.textContent='No extra inputs.';for(const item of inputs){const row=document.createElement('div');row.className='row';const title=document.createElement('span');title.textContent=`${item.name} · ${(item.duration||0).toFixed(1)}s · ${item.channels} ch · ${item.sampleRate} Hz`;
 const role=document.createElement('select');role.setAttribute('aria-label',`Role for ${item.name}`);for(const r of roles)role.add(new Option(r,r));role.value=item.role;role.onchange=()=>{item.role=role.value;refresh()};
 const state=document.createElement('select');state.setAttribute('aria-label',`Game state for ${item.name}`);for(const st of states)state.add(new Option(st,st));state.value=item.state;state.onchange=()=>{item.state=state.value;refresh()};
 const remove=document.createElement('button');remove.textContent='Remove';remove.onclick=()=>{inputs=inputs.filter(x=>x!==item);refresh()};row.append(title,role,state,remove);list.append(row)}const r=readiness();$('projectChecklist').replaceChildren(...r.checks.map(([label,ready],i)=>{const p=document.createElement('p');if([1,3,4,6,7].includes(i)){const key={1:'meter',3:'coverage',4:'joins',6:'mix',7:'engine'}[i],check=document.createElement('input');check.type='checkbox';check.checked=!!confirmations[key];check.onchange=()=>{confirmations[key]=check.checked;refresh()};p.append(check,document.createTextNode(' '+label+' · creator approval'))}else p.textContent=`${ready?'✓':'○'} ${label}`;return p}));}
window.PulseProject={sourceChanged(){confirmations={};refresh()},refresh};
$('projectFiles').onchange=async e=>{const files=[...e.target.files];e.target.value='';for(const file of files){if(inputs.length>=24){$('projectInputList').textContent='Maximum 24 extra inputs. Remove one to continue.';break}if(!/\.wav$/i.test(file.name)||file.size>50*1024*1024||inputs.reduce((n,x)=>n+x.size,0)+file.size>150*1024*1024){$('projectInputList').textContent='Use WAV files up to 50 MB each (150 MB combined).';continue}try{const bytes=await file.arrayBuffer(),header=new Uint8Array(bytes,0,Math.min(12,bytes.byteLength));if(header.length<12||String.fromCharCode(...header.slice(0,4))!=='RIFF'||String.fromCharCode(...header.slice(8,12))!=='WAVE')throw Error();const ctx=new (window.AudioContext||window.webkitAudioContext)();let b;try{b=await ctx.decodeAudioData(bytes)}finally{await ctx.close()}if(b.duration>600||b.numberOfChannels>2)throw Error();inputs.push({name:clean(file.name),size:file.size,duration:b.duration,channels:b.numberOfChannels,sampleRate:b.sampleRate,role:'Riff',state:'Custom'});refresh()}catch{$('projectInputList').textContent=`Could not read ${clean(file.name)}. Use a mono or stereo PCM WAV under 10 minutes.`}}};
$('clearProjectInputs').onclick=()=>{inputs=[];refresh()};
$('downloadProjectPlan').onclick=()=>{const p={format:'pulse-project-plan',version:1,source:snapshot().source,grid:snapshot().grid,inputs,confirmations,readiness:readiness(),note:'File references only. Reload matching WAVs. No audio embedded.'};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));a.href=url;a.download='pulse-project-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)};
$('importProjectPlan').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>200000)throw Error();const p=JSON.parse(await file.text());if(p.format!=='pulse-project-plan'||p.version!==1||!Array.isArray(p.inputs)||p.inputs.length>24)throw Error();const valid=p.inputs.every(x=>typeof x.name==='string'&&x.name.length<=100&&roles.includes(x.role)&&states.includes(x.state)&&Number.isFinite(x.duration)&&x.duration>=0&&x.duration<=600&&Number.isFinite(x.size)&&x.size>=0&&x.size<=50*1024*1024&&[1,2].includes(x.channels)&&Number.isFinite(x.sampleRate)&&x.sampleRate>0);if(!valid)throw Error();confirmations=Object.fromEntries(['meter','coverage','joins','mix','engine'].map(k=>[k,p.confirmations?.[k]===true]));inputs=p.inputs.map(x=>({name:x.name,size:x.size,duration:x.duration,channels:x.channels,sampleRate:x.sampleRate,role:x.role,state:x.state}));refresh();$('projectInputList').prepend(document.createTextNode('Plan opened. Reload the referenced WAVs before using their audio. '))}catch{$('projectInputList').textContent='Invalid project plan. Existing inputs were kept.'}};
setInterval(()=>{if($('projectWorkspace').open)refresh()},1500);refresh();
})();
